// Passo 1: conferimos que veio uma lista de verdade.
function atenderFila(fila, novoCliente) {
  if (!Array.isArray(fila)) {
    throw new Error('fila precisa ser uma lista');
  }

  // Passo 2: shift tira o primeiro da fila e devolve ele.
  const atendido = fila.shift();

  // Passo 3: push coloca o novo cliente no fim da fila.
  fila.push(novoCliente);

  // Passo 4: devolvemos quem foi atendido e a fila atualizada.
  return { atendido, fila };
}

console.log(atenderFila(['Ana', 'Beto'], 'Caio'));
// imprime: { atendido: 'Ana', fila: ['Beto', 'Caio'] }
